def build_prefix(a):
    prefix = [0] * (len(a) + 1)
    for i, x in enumerate(a):
        prefix[i + 1] = prefix[i] + x
    return prefix

def range_sum(prefix, l, r):
    return prefix[r + 1] - prefix[l]

p = build_prefix([2, 4, 1, 7, 3])
print(range_sum(p, 1, 3))
print(range_sum(p, 0, 4))
